mapper.select:
select MST_FEEINFO.FEE_ID id, MST_FEEINFO.FEE_NAME text from MST_FEEINFO where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther}) and MST_FEEINFO.CHARGE_TYPE = #{chargeType02} AND MST_FEEINFO.FEE_TYPE IN (#{feeType06},#{feeType07},#{feeType14})
and (MST_FEEINFO.FEE_ID like concat(concat('%', #{search}), '%') or MST_FEEINFO.FEE_NAME like concat(concat('%', #{search}), '%'))
and MST_FEEINFO.FEE_ID = #{initValue}
union all select DISTINCT MF.FEE_ID id, CONCAT(MF.FEE_ID ,CONCAT( ':' , MF.FEE_NAME)) text from FIN_CASH_INFO FCI,FIN_PRODUCT FP,MST_FEEINFO MF,FIN_PRODUCT_ADD FPD ,FIN_CASH_PAY_RULE FCPR ,PTL_SEC_ACCT PSA,STL_SEC_ACCT_INFO SSAI where MF.APPLY_TYPE in (#{relationProd}, #{relationOther}) and FCI.FINPROD_ID = FP.FINPROD_ID and FCI.FEE_ID = MF.FEE_ID and FP.FINPROD_ID = FPD.FINPROD_ID and FCI.CASH_ID = FCPR.CASH_ID and PSA.PORTFOLIO_ID = FPD.PORTFOLIO_ID and SSAI.SEC_ACCT_ID = PSA.ACCT_NO and FCI.CASH_TYPE_1 = #{cashType1} and FCPR.PAY_CYCLE = #{payCycle} and SSAI.SEC_ACCT_ID = #{secAcctId} and MF.CHARGE_TYPE = #{chargeType01} AND (FCI.IS_CALC IS NULL OR FCI.IS_CALC = #{yes}) AND MF.FEE_TYPE IN (#{feeType06},#{feeType07},#{feeType14})
and (MF.FEE_ID like concat(concat('%', #{search}), '%') or MF.FEE_NAME like concat(concat('%', #{search}), '%'))
and MF.FEE_ID = #{initValue}

    	select distinct DATE_FORMAT(max(TPD.MDATE), '%Y-%m-%d')
    	from TRD_FIN_PRODUCT_DEAL_TOTAL TFPD, TRD_PRODUCT_DEAL TPD, TRD_TRADE_FEE_DETAIL TTFD
    	where TFPD.TOTLE_TRADE_ID = TPD.TOTLE_TRADE_ID
    	and TPD.TRADE_ID = TTFD.TRADE_ID

			and TFPD.SEC_MANAGE_ACCT_ID = #{secAcctId}

    	and TFPD.IS_CANCEL = #{isCancel}
		and TFPD.TRADE_STATUS = #{tradeStatus}
    	and TTFD.FEE_TYPE = #{feeType1}
    	and #{cdate} >= DATE_FORMAT(TPD.MDATE, '%Y-%m-%d')

    	select sum(IFNULL(PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE,0)) 
    	from PTL_FEE_POSITION

			LEFT JOIN PTL_SEC_ACCT PSA 
			ON PSA.PORTFOLIO_ID = PTL_FEE_POSITION.PORTFOLIO_ID
			INNER JOIN STL_SEC_ACCT_INFO SSAI 
      		ON SSAI.SEC_ACCT_ID = PSA.ACCT_NO AND SSAI.REGIST_ORG = PTL_FEE_POSITION.PTL_FEE_PLACE

   		WHERE PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType1}
			AND PTL_FEE_POSITION.CDATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d')-1

				AND PSA.ACCT_NO = #{secAcctId}


				AND PTL_FEE_POSITION.PTL_FEE_PLACE = #{org}

SELECT SUM(IFNULL(TDY_UNPAID_INTINCEXP, 0)) FROM (
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and CDATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d') - 1
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS NULL
	UNION ALL
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and CDATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d') - 1
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS not NULL
	)

		select FFAS.ACCR_STR_DATE 
		from fin_cash_info FCI,FIN_FLOAT_ACCRUAL_SCHE FFAS
        where FCI.finprod_id = #{finprodId}
        and FCI.cash_type_1 = #{CASH_TYPE_1_03}
        and FCI.cash_type_2 = #{CASH_TYPE_2_C04}
        and FFAS.CASH_ID = FCI.cash_id
        and FFAS.ACCR_DATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d')

SELECT ptl.PORTFOLIO_ID ptlId, ptl.PORTFOLIO_NAME portFolioName, tpd.FINPROD_TYPE2 tradeType, tpd.PS ps, asset.FINPROD_MARKET_ID assetCode, asset.finprod_abbr assetName, tpd.TRADE_AMT tradeAmt, DATE_FORMAT(tpd.TRADE_DATE, '%Y-%m-%d') tradeDate, tdf.FEE_TYPE feeType, tdf.FEE_AMT payAmt, tpd.trade_id tradeId, tpd.SEC_MANAGE_ACCT_ID secAcctId FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.trade_id = tpda.trade_id LEFT JOIN TRD_TRADE_FEE_DETAIL tdf ON tpd.trade_id = tdf.trade_id LEFT JOIN PTL_PORTFOLIO ptl ON tpda.PORTFOLIO_ID = ptl.PORTFOLIO_ID LEFT JOIN fin_product asset ON tpd.finprod_id = asset.finprod_id WHERE tpd.TRADE_STATUS = #{TRADE_STATUS_01} AND tpd.IS_CANCEL = #{IS_CANCEL_N}
AND tpd.SEC_MANAGE_ACCT_ID = #{secAcctId}
AND tdf.fee_type = #{feeType1} AND tpd.TRADE_DATE BETWEEN STR_TO_DATE(#{startDate}, '%Y-%m-%d') AND STR_TO_DATE(#{enddate}, '%Y-%m-%d') AND tpda.PORTFOLIO_ID = #{ptlId} AND tpd.FINPROD_TYPE2 != #{FINPROD_TYPE2_C11}

select FPA.FINPROD_ID finprodId, BPP.BRANCH branch, '' sFinprodId, SUM(IFNULL(BPP.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE BPP, FIN_PRODUCT_ADD FPA, FIN_PRODUCT FP where BPP.FINPROD_ID = FPA.FINPROD_ID and FPA.FINPROD_ID = FP.FINPROD_ID
and FPA.PORTFOLIO_ID = #{ptlId}
and BPP.FEE_TYPE = #{feeType}
and BPP.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d')
and BPP.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') -1
and BPP.P_FINPROD_ID is NULL group by FPA.FINPROD_ID, BPP.BRANCH union all
select FPA.FINPROD_ID finprodId, BPP.BRANCH branch, BPP.FINPROD_ID sFinprodId, SUM(IFNULL(BPP.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE BPP, FIN_PRODUCT_ADD FPA, FIN_PRODUCT FP,FIN_PRODUCT F1 where BPP.P_FINPROD_ID = FPA.FINPROD_ID and FPA.FINPROD_ID = FP.FINPROD_ID AND F1.P_FINPROD_ID=FPA.FINPROD_ID
and FPA.PORTFOLIO_ID = #{ptlId}
and BPP.FEE_TYPE = #{feeType}
and BPP.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d')
and BPP.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') -1
group by FPA.FINPROD_ID, BPP.BRANCH,BPP.FINPROD_ID union all
select FPA.FINPROD_ID finprodId, 0 branch, '' sFinprodId, SUM(IFNULL(PFP.TDY_ACCUMUL_PAY_FEE, 0)) actPayAmt from PTL_FEE_POSITION PFP, FIN_PRODUCT_ADD FPA, FIN_PRODUCT FP where PFP.PORTFOLIO_ID = FPA.PORTFOLIO_ID and FPA.FINPROD_ID = FP.FINPROD_ID
and FPA.PORTFOLIO_ID = #{ptlId}
and PFP.PTL_FEE_TYPE = #{feeType} and PFP.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') - 1 and FP.p_Finprod_Id is null group by FPA.FINPROD_ID

SELECT TEMP.finprodMarketId finprodMarketId, TEMP.finprodId finprodId, TEMP.sFinprodId sFinprodId, TEMP.feeId feeId, SDL.item_value basicBill, TEMP.feeName feeName, TEMP.feeType feeType, TEMP.calcStartDate calcStartDate, TEMP.calcEndDate calcEndDate, TEMP.ccy ccy, TEMP.actPayAmt actPayAmt, TEMP.payAmt payAmt FROM( SELECT FPA.PORTFOLIO_ID finprodMarketId ,FP.Finprod_Id finprodId ,NULL as sFinprodId ,MF.FEE_ID feeId ,MF.BASIC_BILL basicBill ,MF.Fee_Name feeName ,BPP.FEE_TYPE feeType ,TPD.MDATE as calcStartDate ,STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') calcEndDate ,FCI.ccy ,BPP.TDY_UNPAID_INTINCEXP as actPayAmt ,BPP.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO FCI INNER JOIN FIN_CASH_PAY_RULE FCPR ON FCI.CASH_ID = FCPR.CASH_ID
AND FCPR.PAY_CYCLE != #{payCycle}
AND FCPR.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO MF ON FCI.FEE_ID = MF.FEE_ID AND MF.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE BPP ON FCI.FINPROD_ID = BPP.FINPROD_ID AND FCI.BRANCH = BPP.BRANCH and FCI.CASH_TYPE_2 = BPP.FEE_TYPE LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL TPD on FCI.FINPROD_ID = TPD.FINPROD_ID AND FCI.BRANCH = TPD.BRANCH AND TPD.FINPROD_TYPE2 = BPP.FEE_TYPE LEFT JOIN FIN_PRODUCT FP ON FCI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON FP.FINPROD_ID = FPA.FINPROD_ID WHERE FCI.CASH_TYPE_1 = #{cashType1} AND FP.P_FINPROD_ID is null AND FPA.PORTFOLIO_ID = #{ptlId} AND FP.FINPROD_ID = #{finprodId} AND MF.FEE_ID = #{feeId} AND BPP.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BPP.FINPROD_ID AND B.BRANCH = BPP.BRANCH AND BPP.FEE_TYPE = B.FEE_TYPE AND B.CDATE <STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d')) UNION SELECT FPA.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT1.FINPROD_MARKET_ID finprodId ,FP.FINPROD_ID as sFinprodId ,MF.FEE_ID feeId ,MF.BASIC_BILL basicBill ,MF.Fee_Name feeName ,BPP.FEE_TYPE feeType ,TPD.MDATE as calcStartDate ,STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') calcEndDate ,FCI.ccy ,BPP.TDY_UNPAID_INTINCEXP as actPayAmt ,BPP.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO FCI INNER JOIN FIN_CASH_PAY_RULE FCPR ON FCI.CASH_ID = FCPR.CASH_ID
AND FCPR.PAY_CYCLE != #{payCycle}
AND FCPR.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO MF ON FCI.FEE_ID = MF.FEE_ID AND MF.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE BPP ON FCI.FINPROD_ID = BPP.FINPROD_ID AND FCI.BRANCH = BPP.BRANCH and FCI.CASH_TYPE_2 = BPP.FEE_TYPE LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL TPD on FCI.FINPROD_ID = TPD.FINPROD_ID AND FCI.BRANCH = TPD.BRANCH AND TPD.FINPROD_TYPE2 = BPP.FEE_TYPE LEFT JOIN FIN_PRODUCT FP ON FCI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON BPP.FINPROD_ID = FIN_PRODUCT1.FINPROD_ID
LEFT JOIN FIN_PRODUCT_ADD FPA ON FIN_PRODUCT1.FINPROD_ID = FPA.FINPROD_ID WHERE FCI.CASH_TYPE_1 = #{cashType1} AND FP.P_FINPROD_ID is not null AND FPA.PORTFOLIO_ID = #{ptlId} AND FP.P_FINPROD_ID = #{finprodId} AND MF.FEE_ID = #{feeId} AND BPP.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BPP.FINPROD_ID AND B.BRANCH = BPP.BRANCH AND BPP.FEE_TYPE = B.FEE_TYPE
AND B.CDATE <STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d'))
union all
select PP.PORTFOLIO_ID finprodMarketId ,FPA.FINPROD_ID finprodId ,'' as sFinprodId ,MF.FEE_ID feeId ,MF.BASIC_BILL basicBill ,MF.Fee_Name feeName ,PFP.PTL_FEE_TYPE feeType ,IFNULL(TPD.MDATE,PP.vdate) as calcStartDate ,STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') calcEndDate ,FCI.ccy ,PFP.TDY_ACCUMUL_PAY_FEE as actPayAmt ,PFP.TDY_ACCUMUL_PAY_FEE as payAmt from PTL_FEE_POSITION PFP, FIN_PRODUCT_ADD FPA, PTL_PORTFOLIO PP,MST_FEEINFO MF , FIN_CASH_INFO FCI LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL TPD on FCI.FINPROD_ID = TPD.FINPROD_ID AND FCI.BRANCH = TPD.BRANCH and FCI.CASH_TYPE_2 = TPD.FINPROD_TYPE2 where PFP.PORTFOLIO_ID = FPA.PORTFOLIO_ID and FPA.PORTFOLIO_ID = PP.PORTFOLIO_ID and FCI.FINPROD_ID = FPA.FINPROD_ID and FCI.CASH_TYPE_1 = #{cashType1} and FCI.CASH_TYPE_2 = #{cashType2_C04} and FCI.FEE_ID = MST_FEEINFO.FEE_ID and PFP.PTL_FEE_TYPE = FCI.CASH_TYPE_2 AND MF.CHARGE_TYPE = #{chargeType} and FPA.PORTFOLIO_ID = #{ptlId} and PFP.PTL_FEE_TYPE = #{feeType} and PFP.CDATE = STR_TO_DATE(#{calcEndDate}, '%Y-%m-%d') - 1 and PP.PROFIT_TYPE = #{profitType} )TEMP left join sys_datadict_list SDL on TEMP.basicBill = SDL.item_code and SDL.dict_code = 'BILL_BASE_FEE_KIND'


    select sum(PTPD.THEORY_AMT)-sum(TTFD.FEE_AMT) from 
    PA_TRD_PRODUCT_DEAL PTPD ,TRD_TRADE_FEE_DETAIL TTFD,TRD_PRODUCT_DEAL TPD,FIN_PRODUCT_ADD FPA
		WHERE TTFD.TRADE_ID = PTPD.TRADE_ID
		AND TPD.TRADE_ID = PTPD.TRADE_ID
		AND FPA.FINPROD_ID = TPD.FINPROD_ID
		AND TPD.FINPROD_ID = #{finprodId}
	    AND TPD.IS_CANCEL = #{noFlag}
		AND TPD.TRADE_STATUS = #{tradeStatus}

	  	AND FPA.PORTFOLIO_ID = #{ptlId}


		AND TTFD.FEE_ID = #{feeId}


		AND TPD.TRADE_DATE <= STR_TO_DATE(#{payDate},'%Y-%m-%d')

		AND TPD.IS_CLEAN = #{isClean}

  select IFNULL(sum(IFNULL(fee_amt,0)),0) from trd_trade_fee_detail where fee_type=#{feeType1} and trade_id in(
select deal.trade_id from trd_product_deal deal,trd_product_deal_add add1 ,fin_product prod  
where prod.finprod_type2 in('F01','F02','F03','F04','F05') and is_cancel='N'
and add1.trade_id=deal.trade_id and add1.portfolio_id=#{ptlId}  
and deal.trade_date <= STR_TO_DATE(#{cdate}, '%Y-%m-%d') and deal.finprod_id=prod.finprod_id and prod.REGIST_ORG=#{org}
)

	select IFNULL(sum(IFNULL(trade_amt,0)),0) 
	from  trd_product_deal deal,trd_product_deal_add add1 ,
		fin_product prod,TRD_TRADE_FEE_DETAIL feed
	where  
	deal.finprod_id=prod.finprod_id 
	and deal.TRADE_ID = feed.TRADE_ID
	AND deal.IS_CANCEL = #{noFlag}
	and feed.fee_type = #{feeType1} 
	and deal.trade_id = add1.trade_id

 	and deal.SEC_MANAGE_ACCT_ID = #{secAcctId} 


 	and  deal.REGIST_ORG=#{org} 

	and deal.trade_date = STR_TO_DATE(#{cdate}, '%Y-%m-%d')

       select count(*)
        from FIN_CASH_INFO,FIN_PRODUCT,MST_FEEINFO,FIN_PRODUCT_ADD ,FIN_CASH_PAY_RULE
        where MST_FEEINFO.APPLY_TYPE in (#{relationProd}, #{relationOther})
        and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
        and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID
        and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
        and FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
        and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
        and FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
        and (CASE WHEN MST_FEEINFO.FEE_TYPE = #{feeType_03} THEN 0 WHEN #{feeType_04} THEN 0 WHEN #{feeType_12} THEN 0 ELSE 1 END) = 1

        and FIN_CASH_INFO.FINPROD_ID = #{finprodId}



			and FIN_PRODUCT_ADD.PORTFOLIO_ID in 

				#{item}


      and MST_FEEINFO.CHARGE_TYPE = #{chargeType01}

          and MST_FEEINFO.FEE_ID = #{initValue}

         and not exists (select 1 from TRD_PRODUCT_DEAL where FIN_CASH_INFO.CASH_ID = TRD_PRODUCT_DEAL.CASH_ID
         and TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag}
         and TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus}

        and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
        )

   		SELECT sum(IFNULL(PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE,0))
   		FROM PTL_FEE_POSITION

			LEFT JOIN PTL_SEC_ACCT PSA 
			ON PSA.PORTFOLIO_ID = PTL_FEE_POSITION.PORTFOLIO_ID
			INNER JOIN STL_SEC_ACCT_INFO SSAI 
			ON SSAI.SEC_ACCT_ID = PSA.ACCT_NO AND SSAI.REGIST_ORG = PTL_FEE_POSITION.PTL_FEE_PLACE

   		WHERE PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType1}
			AND PTL_FEE_POSITION.CDATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d')-1

				AND PSA.ACCT_NO = #{secAcctId}


				AND PTL_FEE_POSITION.PTL_FEE_PLACE = #{org}

mapper.sql:
SELECT '${pendingStatus}' effectStatus , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID secAcctId , '' AS feeId , '' AS feeName , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 feeType, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 AS feeType1, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE AS VDATE , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE AS MDATE , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE AS payDate , payAmt.payAmt AS feeAmt , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_AMT AS actPayAmt , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID tradeId , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE positionStartDate , WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE positionEndDate FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL LEFT JOIN ( select WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,SUM(WFL_PA_TRD_PRODUCT_DEAL.THEORY_INT) payAmt from WFL_PA_TRD_PRODUCT_DEAL,WFL_TRD_PRODUCT_DEAL where WFL_TRD_PRODUCT_DEAL.TRADE_ID =WFL_PA_TRD_PRODUCT_DEAL.TRADE_ID group by WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID ) payAmt ON payAmt.TOTLE_TRADE_ID = WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID WHERE 1=1 AND WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS=#{effectStatus} AND WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TG_BUSI_TYPE=#{TG_BUSI_TYPE}
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID = #{secAcctId}
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE = STR_TO_DATE(#{mdate}, '%Y-%m-%d')
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE >= STR_TO_DATE(#{payDateStart}, '%Y-%m-%d')
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE <= STR_TO_DATE(#{payDateEnd}, '%Y-%m-%d')
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2= #{feeType}

SELECT '${cancleStatus}' effectStatus , TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID secAcctId , '' AS feeId , '' AS feeName , TRD_TRADE_FEE_DETAIL.FEE_TYPE feeType, TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 AS feeType1, TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE AS VDATE , TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE AS MDATE , TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE AS payDate , payAmt.payAmt AS feeAmt , TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_AMT AS actPayAmt , TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID tradeId , TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE positionStartDate , TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE positionEndDate FROM TRD_FIN_PRODUCT_DEAL_TOTAL LEFT JOIN TRD_TRADE_FEE_DETAIL ON TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = TRD_TRADE_FEE_DETAIL.TRADE_ID LEFT JOIN ( select TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,SUM(PA_TRD_PRODUCT_DEAL.THEORY_AMT) payAmt from PA_TRD_PRODUCT_DEAL,TRD_PRODUCT_DEAL where TRD_PRODUCT_DEAL.TRADE_ID =PA_TRD_PRODUCT_DEAL.TRADE_ID group by TRD_PRODUCT_DEAL.TOTLE_TRADE_ID ) payAmt ON payAmt.TOTLE_TRADE_ID = TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID WHERE 1=1 AND TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS=#{effectStatus} AND TRD_FIN_PRODUCT_DEAL_TOTAL.IS_CANCEL=#{yesFlag} AND TRD_FIN_PRODUCT_DEAL_TOTAL.TG_BUSI_TYPE=#{TG_BUSI_TYPE}
and TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID = #{secAcctId}
and TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE = STR_TO_DATE(#{mdate}, '%Y-%m-%d')
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE >= STR_TO_DATE(#{payDateStart}, '%Y-%m-%d')
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE <= STR_TO_DATE(#{payDateEnd}, '%Y-%m-%d')
and TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2= #{feeType}

SELECT '${effectStatus}' effectStatus , TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID secAcctId , '' AS feeId , '' AS feeName , TRD_TRADE_FEE_DETAIL.FEE_TYPE feeType, TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 AS feeType1, TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE AS VDATE , TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE AS MDATE , TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE AS payDate , payAmt.payAmt AS feeAmt , TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_AMT AS actPayAmt , TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID tradeId , TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE positionStartDate , TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE positionEndDate FROM TRD_FIN_PRODUCT_DEAL_TOTAL LEFT JOIN TRD_TRADE_FEE_DETAIL ON TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = TRD_TRADE_FEE_DETAIL.TRADE_ID LEFT JOIN ( select TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,SUM(PA_TRD_PRODUCT_DEAL.THEORY_AMT) payAmt from PA_TRD_PRODUCT_DEAL,TRD_PRODUCT_DEAL where TRD_PRODUCT_DEAL.TRADE_ID =PA_TRD_PRODUCT_DEAL.TRADE_ID group by TRD_PRODUCT_DEAL.TOTLE_TRADE_ID ) payAmt ON payAmt.TOTLE_TRADE_ID = TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID WHERE 1=1 AND TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS=#{effectStatus} AND TRD_FIN_PRODUCT_DEAL_TOTAL.IS_CANCEL=#{noFlag} AND TRD_FIN_PRODUCT_DEAL_TOTAL.TG_BUSI_TYPE=#{TG_BUSI_TYPE}
and TRD_FIN_PRODUCT_DEAL_TOTAL.SEC_MANAGE_ACCT_ID = #{secAcctId}
and TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE = STR_TO_DATE(#{mdate}, '%Y-%m-%d')
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE >= STR_TO_DATE(#{payDateStart}, '%Y-%m-%d')
and TRD_FIN_PRODUCT_DEAL_TOTAL.SETTLE_DATE <= STR_TO_DATE(#{payDateEnd}, '%Y-%m-%d')
and TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2= #{feeType}
